import itertools, collections
def clusters(g, col):
    cells=[(i,j) for i in range(len(g)) for j in range(len(g[0])) if g[i][j]==col]
    sc=set(cells); seen=set(); out=[]
    for c in cells:
        if c in seen: continue
        q=[c]; seen.add(c); cl=[]
        while q:
            x=q.pop(); cl.append(x)
            for dy,dx in itertools.product((-1,0,1),repeat=2):
                n=(x[0]+dy,x[1]+dx)
                if n in sc and n not in seen: seen.add(n); q.append(n)
        out.append(sorted(cl))
    return out
def corner(g):
    # find color with an L: cells forming vertical+horizontal line sharing endpoint
    best=None
    for col in set(x for r in g for x in r):
        cls=clusters(g,col)
        for cl in cls:
            s=set(cl)
            rows=collections.Counter(i for i,j in cl); cols=collections.Counter(j for i,j in cl)
            vr=[r for r,c in rows.items() if c>=3]; hc=[c for c,n in cols.items() if n>=3]
            if vr and hc:
                for r in vr:
                    for c in hc:
                        if (r,c) in s:
                            vlen=rows[r]; hlen=cols[c]
                            cand=(vlen,hlen,col,r,c,len(cl))
                            if best is None or (vlen+hlen)>(best[0]+best[1]): best=cand
    return best
