def clusters4(g,col,conn=8):
    cells=[(i,j) for i in range(len(g)) for j in range(len(g[0])) if g[i][j]==col]
    sc=set(cells); seen=set(); out=[]
    offs=[(dy,dx) for dy in range(-1,2) for dx in range(-1,2) if (dy,dx)!=(0,0) and (conn==8 or abs(dy)+abs(dx)==1)]
    for c in cells:
        if c in seen: continue
        q=[c]; seen.add(c); cl=[]
        while q:
            x=q.pop(); cl.append(x)
            for dy,dx in offs:
                n=(x[0]+dy,x[1]+dx)
                if n in sc and n not in seen: seen.add(n); q.append(n)
        out.append(sorted(cl))
    return out
def norm(cl):
    mi=min(i for i,j in cl); mj=min(j for i,j in cl)
    return tuple(sorted((i-mi,j-mj) for i,j in cl))
def find_corner(g):
    res=[]
    for col in set(x for r in g for x in r):
        for cl in clusters4(g,col):
            s=set(cl)
            colcount=collections.Counter(j for i,j in cl); rowcount=collections.Counter(i for i,j in cl)
            vcands=[(j,min(i for i,jj in cl if jj==j)) for j,n in colcount.items() if n>=2]
            hcands=[(i,min(j for ii,j in cl if ii==i)) for i,n in rowcount.items() if n>=2]
            for j,topi in vcands:
                for i,leftj in hcands:
                    if (i,j) in s:  # intersection
                        res.append((col,i,j,topi,leftj))
    return res
